```python
import httpx

def fetch_user(user_id):
    for attempt in range(2):
        resp = httpx.get(f'https://api.internal.example.com/users/{user_id}', timeout=5)
        if resp.status_code < 500:
            break
    resp.raise_for_status()
    return resp.json()
